import{at as e,it as t,n,vt as r}from"./chunks/framework.BFgrh0AM.js";var i=JSON.parse(`{"title":"Class: World","description":"","frontmatter":{},"headers":[],"relativePath":"api/@jsprismarine/prismarine/classes/World.md","filePath":"api/@jsprismarine/prismarine/classes/World.md"}`),a={name:`api/@jsprismarine/prismarine/classes/World.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<p><a href="./../../../">JSPrismarine</a> / <a href="./../">@jsprismarine/prismarine</a> / World</p><h1 id="class-world" tabindex="-1">Class: World <a class="header-anchor" href="#class-world" aria-label="Permalink to “Class: World”">​</a></h1><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L494" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:494</a></p><h2 id="implements" tabindex="-1">Implements <a class="header-anchor" href="#implements" aria-label="Permalink to “Implements”">​</a></h2><ul><li><a href="./Service.html"><code>Service</code></a></li></ul><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to “Constructors”">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to “Constructor”">​</a></h3><blockquote><p><strong>new World</strong>(<code>__namedParameters</code>): <code>World</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L624" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:624</a></p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="namedparameters" tabindex="-1">__namedParameters <a class="header-anchor" href="#namedparameters" aria-label="Permalink to “__namedParameters”">​</a></h5><p><a href="./../#worlddata"><code>WorldData</code></a></p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>World</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to “Properties”">​</a></h2><h3 id="item-entity-limit" tabindex="-1">ITEM_ENTITY_LIMIT <a class="header-anchor" href="#item-entity-limit" aria-label="Permalink to “ITEM_ENTITY_LIMIT”">​</a></h3><blockquote><p><code>readonly</code> <code>static</code> <strong>ITEM_ENTITY_LIMIT</strong>: <code>2048</code> = <code>2048</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2585" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2585</a></p><p>The most dropped stacks one world keeps on the ground at once.</p><p>Neither edition publishes a number like this, and neither needs one. Java bounds its item entities with a 6000-tick despawn, and both editions merge stacks that land together, which this server does too in <code>entity/other/Item.ts</code>. What neither bounds is a burst. BlockUpdateScheduler lets one tick process 4096 positions, every one of which can destroy a block and roll its loot table, and a world that has just generated hundreds of chunks has that much work waiting in it. The reported crash was over 10,000 stacks on the ground, each one falling, comparing itself against its neighbors to merge, and going out to every player in range, every tick.</p><p>The number is this server&#39;s own judgement rather than anything Mojang publishes: well past what play produces, well short of what the per-tick merge pass can carry.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="addentity" tabindex="-1">addEntity() <a class="header-anchor" href="#addentity" aria-label="Permalink to “addEntity()”">​</a></h3><blockquote><p><strong>addEntity</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2832" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2832</a></p><p>Adds an entity body to the level. Generic bodies a data runtime can build are handed to it first; its replacement body re-enters here after the runtime has indexed it, so the replacement is added normally.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity" tabindex="-1">entity <a class="header-anchor" href="#entity" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity to add.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="addgameeventlistener" tabindex="-1">addGameEventListener() <a class="header-anchor" href="#addgameeventlistener" aria-label="Permalink to “addGameEventListener()”">​</a></h3><blockquote><p><strong>addGameEventListener</strong>(<code>listener</code>): () =&gt; <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3236" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3236</a></p><p>Registers a listener for Java game events in this dimension.</p><p>Listeners are stored in the chunk section containing their position. Call <a href="#movegameeventlistener">World.moveGameEventListener</a> after a dynamic listener moves.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="listener" tabindex="-1">listener <a class="header-anchor" href="#listener" aria-label="Permalink to “listener”">​</a></h5><p><code>GameEventListener</code></p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p>A function that unregisters the listener.</p><p>() =&gt; <code>void</code></p><hr><h3 id="announcegamerule" tabindex="-1">announceGameRule() <a class="header-anchor" href="#announcegamerule" aria-label="Permalink to “announceGameRule()”">​</a></h3><blockquote><p><strong>announceGameRule</strong>(<code>name</code>, <code>value</code>, <code>editable</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3594" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3594</a></p><p>Tells everyone in this world that a game rule changed. Called by the level, whose rules these are, for each of its worlds.</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><h5 id="value" tabindex="-1">value <a class="header-anchor" href="#value" aria-label="Permalink to “value”">​</a></h5><p><code>number</code> | <code>boolean</code></p><h5 id="editable" tabindex="-1">editable <a class="header-anchor" href="#editable" aria-label="Permalink to “editable”">​</a></h5><p><code>boolean</code></p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="attachchangesink" tabindex="-1">attachChangeSink() <a class="header-anchor" href="#attachchangesink" aria-label="Permalink to “attachChangeSink()”">​</a></h3><blockquote><p><strong>attachChangeSink</strong>(<code>sink</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L684" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:684</a></p><p>Gives this world somewhere to report its changes.</p><p>Attached from outside rather than built here, for the same reason a player does not build its own session: the world would otherwise have to know the network layer exists in order to construct a piece of it.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="sink" tabindex="-1">sink <a class="header-anchor" href="#sink" aria-label="Permalink to “sink”">​</a></h5><p><code>WorldChangeSink</code></p><p>Where changes go from now on.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="blockentitychanged" tabindex="-1">blockEntityChanged() <a class="header-anchor" href="#blockentitychanged" aria-label="Permalink to “blockEntityChanged()”">​</a></h3><blockquote><p><strong>blockEntityChanged</strong>(<code>position</code>, <code>tags</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2027" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2027</a></p><p>Reports that the block entity at a position is now these tags.</p><p>What makes this world a import(&#39;../blockentity/blockEntityWrite&#39;).BlockEntityWorld, so that every block entity write goes through one place and reaches the clients holding the chunk. Called by <code>writeBlockEntity</code> and by nothing else: it reports rather than writes, and calling it without having written the chunk tells a client something that is not true.</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position" tabindex="-1">position <a class="header-anchor" href="#position" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The block the block entity sits in.</p><h5 id="tags" tabindex="-1">tags <a class="header-anchor" href="#tags" aria-label="Permalink to “tags”">​</a></h5><p><a href="./../../nbt/classes/NBTTagCompound.html"><code>NBTTagCompound</code></a></p><p>Its complete data, as the chunk would serialize it.</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="breakblock" tabindex="-1">breakBlock() <a class="header-anchor" href="#breakblock" aria-label="Permalink to “breakBlock()”">​</a></h3><blockquote><p><strong>breakBlock</strong>(<code>position</code>, <code>player?</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2089" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2089</a></p><p>Destroys the block at a position: takes it out of the world, tells every player, and plays the break where it stood.</p><p>Deliberately idempotent - a position already holding air is left alone and reported as <code>false</code>. <em>Which</em> packet announces a break depends on the breaking mode and the game mode. With server-authoritative block breaking, the default, survival reports a <code>PREDICT_DESTROY_BLOCK</code> in the tick&#39;s <code>PlayerAuthInputPacket</code>. With the client timing breaks, survival sends an InventoryTransaction, on its own or inside the input. Creative sends a PlayerAction in either mode, and a client is free to send more than one. Rather than guess which one to trust, every route calls this, and whichever arrives second finds the work already done. That is what keeps the break from sounding twice.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-1" tabindex="-1">position <a class="header-anchor" href="#position-1" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>the block to destroy.</p><h5 id="player" tabindex="-1">player? <a class="header-anchor" href="#player" aria-label="Permalink to “player?”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>who broke it, when a player did. Decides what it drops.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p><code>true</code> if a block was there and is now gone.</p><hr><h3 id="broadcastmove" tabindex="-1">broadcastMove() <a class="header-anchor" href="#broadcastmove" aria-label="Permalink to “broadcastMove()”">​</a></h3><blockquote><p><strong>broadcastMove</strong>(<code>entity</code>, <code>teleport?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3156" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3156</a></p><p>Tells everyone in this world that an entity has moved.</p><p>Queued rather than sent, and flushed once at the end of the tick - see <a href="./PlayerSession.html#queuemoveactor">PlayerSession.queueMoveActor</a>, which explains why sending each one on its own made mobs move in fits and starts. A move outside the tick waits at most one tick, which is fifty milliseconds and below anything a player can see.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-1" tabindex="-1">entity <a class="header-anchor" href="#entity-1" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity that moved.</p><h5 id="teleport" tabindex="-1">teleport? <a class="header-anchor" href="#teleport" aria-label="Permalink to “teleport?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>Whether clients should snap instead of interpolate.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="dataentities" tabindex="-1">dataEntities() <a class="header-anchor" href="#dataentities" aria-label="Permalink to “dataEntities()”">​</a></h3><blockquote><p><strong>dataEntities</strong>(): <code>LiveEntityRuntime</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3214" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3214</a></p><p>The data-driven entities of this world&#39;s dimension.</p><p>What drives every mob&#39;s behavior: its components, its goals, its brain, the spawn cycle and the despawn pass.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>LiveEntityRuntime</code></p><p>This dimension&#39;s runtime.</p><hr><h3 id="dragonfightsavestate" tabindex="-1">dragonFightSaveState() <a class="header-anchor" href="#dragonfightsavestate" aria-label="Permalink to “dragonFightSaveState()”">​</a></h3><blockquote><p><strong>dragonFightSaveState</strong>(): <code>DragonFightState</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2343" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2343</a></p><p>The fight&#39;s persistable state, without creating a fight that never ran.</p><p>The level&#39;s save reads this; a world whose fight was never asked for answers undefined, and the level keeps whatever the save already held.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>DragonFightState</code> | <code>undefined</code></p><hr><h3 id="dropcontents" tabindex="-1">dropContents() <a class="header-anchor" href="#dropcontents" aria-label="Permalink to “dropContents()”">​</a></h3><blockquote><p><strong>dropContents</strong>(<code>position</code>, <code>contents</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2620" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2620</a></p><p>Puts items on the ground at a position, one entity each.</p><p>Past <a href="#item-entity-limit">World.ITEM_ENTITY_LIMIT</a> stacks in the world the remaining drops are lost rather than spawned. Losing a drop is worse than vanilla and better than the server going down, and it is reported so an operator can tell which happened.</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-2" tabindex="-1">position <a class="header-anchor" href="#position-2" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>where they land, still.</p><h5 id="contents" tabindex="-1">contents <a class="header-anchor" href="#contents" aria-label="Permalink to “contents”">​</a></h5><p>(<a href="./Item.html"><code>Item</code></a> | <a href="./Block.html"><code>Block</code></a> | <code>null</code>)[]</p><p>what to drop; nulls are skipped, so a block that drops nothing for the tool used can say so plainly.</p><h4 id="returns-10" tabindex="-1">Returns <a class="header-anchor" href="#returns-10" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="dropfromblock" tabindex="-1">dropFromBlock() <a class="header-anchor" href="#dropfromblock" aria-label="Permalink to “dropFromBlock()”">​</a></h3><blockquote><p><strong>dropFromBlock</strong>(<code>block</code>, <code>contents</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2634" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2634</a></p><p>Puts what a block yielded on the ground, each stack popping out of the block.</p><p>Where a Bedrock Dedicated Server 1.26.52 puts a block&#39;s drop: at a random spot inside the block, pushed a little sideways and upward; see popOut. The push is what brings stacks from neighboring blocks within the half block they merge at, and merging is what keeps a burst of breaks under <a href="#item-entity-limit">World.ITEM_ENTITY_LIMIT</a>.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="block" tabindex="-1">block <a class="header-anchor" href="#block" aria-label="Permalink to “block”">​</a></h5><p><a href="./../#contentposition"><code>ContentPosition</code></a></p><p>the block they came out of.</p><h5 id="contents-1" tabindex="-1">contents <a class="header-anchor" href="#contents-1" aria-label="Permalink to “contents”">​</a></h5><p>(<a href="./Item.html"><code>Item</code></a> | <a href="./Block.html"><code>Block</code></a> | <code>null</code>)[]</p><p>what to drop, as for <a href="#dropcontents">World.dropContents</a>.</p><h4 id="returns-11" tabindex="-1">Returns <a class="header-anchor" href="#returns-11" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="dropfromplayer" tabindex="-1">dropFromPlayer() <a class="header-anchor" href="#dropfromplayer" aria-label="Permalink to “dropFromPlayer()”">​</a></h3><blockquote><p><strong>dropFromPlayer</strong>(<code>player</code>, <code>contents</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2650" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2650</a></p><p>Drops player-held stacks from the player&#39;s eyes, with Java&#39;s forward toss and pickup delay.</p><p>Java places the item at eye height minus 0.3 blocks and gives it a 0.3-block-per-tick velocity along the view, with its small vanilla spread. The spawn position passed to World.spill is the item&#39;s feet; the item actor reports 0.125 blocks above it.</p><h4 id="parameters-10" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-10" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-1" tabindex="-1">player <a class="header-anchor" href="#player-1" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>The player who dropped the stacks.</p><h5 id="contents-2" tabindex="-1">contents <a class="header-anchor" href="#contents-2" aria-label="Permalink to “contents”">​</a></h5><p>(<a href="./Item.html"><code>Item</code></a> | <a href="./Block.html"><code>Block</code></a> | <code>null</code>)[]</p><p>The stacks to drop; nulls and empty stacks are skipped.</p><h4 id="returns-12" tabindex="-1">Returns <a class="header-anchor" href="#returns-12" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="emitgameevent" tabindex="-1">emitGameEvent() <a class="header-anchor" href="#emitgameevent" aria-label="Permalink to “emitGameEvent()”">​</a></h3><blockquote><p><strong>emitGameEvent</strong>(<code>event</code>, <code>at</code>, <code>sourceId?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3257" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3257</a></p><p>Posts one Java game event to listeners in the already-loaded chunks.</p><h4 id="parameters-11" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-11" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="event" tabindex="-1">event <a class="header-anchor" href="#event" aria-label="Permalink to “event”">​</a></h5><p><code>string</code></p><p>The namespaced Java game event.</p><h5 id="at" tabindex="-1">at <a class="header-anchor" href="#at" aria-label="Permalink to “at”">​</a></h5><p><a href="./../#contentposition"><code>ContentPosition</code></a></p><p>The integer block position where it occurred.</p><h5 id="sourceid" tabindex="-1">sourceId? <a class="header-anchor" href="#sourceid" aria-label="Permalink to “sourceId?”">​</a></h5><p><code>number</code></p><p>The runtime id of its source entity, when one caused it.</p><h4 id="returns-13" tabindex="-1">Returns <a class="header-anchor" href="#returns-13" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="entityequipmentchanged" tabindex="-1">entityEquipmentChanged() <a class="header-anchor" href="#entityequipmentchanged" aria-label="Permalink to “entityEquipmentChanged()”">​</a></h3><blockquote><p><strong>entityEquipmentChanged</strong>(<code>entity</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1576" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1576</a></p><p>Tells everyone watching that an entity is holding or wearing something new.</p><p>Called from the one place equipment is written, <code>entity/data/liveBodies.ts</code>, which has already dropped the writes that changed nothing.</p><h4 id="parameters-12" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-12" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-2" tabindex="-1">entity <a class="header-anchor" href="#entity-2" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>Whose equipment changed.</p><h4 id="returns-14" tabindex="-1">Returns <a class="header-anchor" href="#returns-14" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="getblock" tabindex="-1">getBlock() <a class="header-anchor" href="#getblock" aria-label="Permalink to “getBlock()”">​</a></h3><blockquote><p><strong>getBlock</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>layer?</code>): <code>Promise</code>&lt;<a href="./Block.html"><code>Block</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1167" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1167</a></p><p>The block at a position, carrying the state the chunk holds.</p><p>Every one of the palette&#39;s 22079 states resolves, because the names a chunk can hold come out of the same content build this method reads. The properties travel with the name, so a lit lamp, a half slab and a stair on its side each read their own facts rather than the ones their default state has.</p><h4 id="parameters-13" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-13" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x" tabindex="-1">x <a class="header-anchor" href="#x" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y" tabindex="-1">y <a class="header-anchor" href="#y" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z" tabindex="-1">z <a class="header-anchor" href="#z" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="layer" tabindex="-1">layer? <a class="header-anchor" href="#layer" aria-label="Permalink to “layer?”">​</a></h5><p><code>number</code> = <code>0</code></p><h4 id="returns-15" tabindex="-1">Returns <a class="header-anchor" href="#returns-15" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Block.html"><code>Block</code></a>&gt;</p><h4 id="throws" tabindex="-1">Throws <a class="header-anchor" href="#throws" aria-label="Permalink to “Throws”">​</a></h4><p>When no registry names the block the chunk holds, which is a corrupt chunk or a world saved against a plugin that is no longer loaded. This used to answer air, and air is a position a caller is free to build in, so the block was lost on the next write.</p><hr><h3 id="getblockstate" tabindex="-1">getBlockState() <a class="header-anchor" href="#getblockstate" aria-label="Permalink to “getBlockState()”">​</a></h3><blockquote><p><strong>getBlockState</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>layer?</code>): <code>Promise</code>&lt;<a href="./BlockState.html"><code>BlockState</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1151" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1151</a></p><p>The exact block state at a position, properties included.</p><p><code>getBlock</code> answers &quot;which block is this&quot;, collapsing every state of it onto one <code>Block</code>. Anything the client resolves by runtime id - break sounds, destroy particles - needs the state itself, because that is what the id identifies.</p><h4 id="parameters-14" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-14" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-1" tabindex="-1">x <a class="header-anchor" href="#x-1" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-1" tabindex="-1">y <a class="header-anchor" href="#y-1" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-1" tabindex="-1">z <a class="header-anchor" href="#z-1" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="layer-1" tabindex="-1">layer? <a class="header-anchor" href="#layer-1" aria-label="Permalink to “layer?”">​</a></h5><p><code>number</code> = <code>0</code></p><h4 id="returns-16" tabindex="-1">Returns <a class="header-anchor" href="#returns-16" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./BlockState.html"><code>BlockState</code></a>&gt;</p><hr><h3 id="getblockupdates" tabindex="-1">getBlockUpdates() <a class="header-anchor" href="#getblockupdates" aria-label="Permalink to “getBlockUpdates()”">​</a></h3><blockquote><p><strong>getBlockUpdates</strong>(): <code>BlockUpdateScheduler</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2316" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2316</a></p><p>The queue of positions waiting to react to a change - see BlockUpdateScheduler.</p><h4 id="returns-17" tabindex="-1">Returns <a class="header-anchor" href="#returns-17" aria-label="Permalink to “Returns”">​</a></h4><p><code>BlockUpdateScheduler</code></p><hr><h3 id="getblockwriteversion" tabindex="-1">getBlockWriteVersion() <a class="header-anchor" href="#getblockwriteversion" aria-label="Permalink to “getBlockWriteVersion()”">​</a></h3><blockquote><p><strong>getBlockWriteVersion</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1223" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1223</a></p><p>The latest block-write version, unique across world instances and monotonic per world.</p><h4 id="returns-18" tabindex="-1">Returns <a class="header-anchor" href="#returns-18" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getchunk" tabindex="-1">getChunk() <a class="header-anchor" href="#getchunk" aria-label="Permalink to “getChunk()”">​</a></h3><blockquote><p><strong>getChunk</strong>(<code>cx</code>, <code>cz</code>, <code>options?</code>): <code>Promise</code>&lt;<code>Chunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1184" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1184</a></p><p>Returns the chunk in the specifies x and z, if the chunk doesn&#39;t exists it is generated.</p><h4 id="parameters-15" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-15" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="cx" tabindex="-1">cx <a class="header-anchor" href="#cx" aria-label="Permalink to “cx”">​</a></h5><p><code>number</code></p><h5 id="cz" tabindex="-1">cz <a class="header-anchor" href="#cz" aria-label="Permalink to “cz”">​</a></h5><p><code>number</code></p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#chunkrequestoptions"><code>ChunkRequestOptions</code></a></p><p>How badly the chunk is wanted. Defaults to <code>immediate</code>, which is what a caller that is about to read blocks out of it means.</p><h4 id="returns-19" tabindex="-1">Returns <a class="header-anchor" href="#returns-19" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Chunk</code>&gt;</p><hr><h3 id="getchunkat" tabindex="-1">getChunkAt() <a class="header-anchor" href="#getchunkat" aria-label="Permalink to “getChunkAt()”">​</a></h3><h4 id="call-signature" tabindex="-1">Call Signature <a class="header-anchor" href="#call-signature" aria-label="Permalink to “Call Signature”">​</a></h4><blockquote><p><strong>getChunkAt</strong>(<code>x</code>): <code>Promise</code>&lt;<code>Chunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1722" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1722</a></p><p>Returns a chunk from a block position&#39;s x and z coordinates.</p><h5 id="parameters-16" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-16" aria-label="Permalink to “Parameters”">​</a></h5><h6 id="x-2" tabindex="-1">x <a class="header-anchor" href="#x-2" aria-label="Permalink to “x”">​</a></h6><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><h5 id="returns-20" tabindex="-1">Returns <a class="header-anchor" href="#returns-20" aria-label="Permalink to “Returns”">​</a></h5><p><code>Promise</code>&lt;<code>Chunk</code>&gt;</p><h4 id="call-signature-1" tabindex="-1">Call Signature <a class="header-anchor" href="#call-signature-1" aria-label="Permalink to “Call Signature”">​</a></h4><blockquote><p><strong>getChunkAt</strong>(<code>x</code>, <code>z</code>): <code>Promise</code>&lt;<code>Chunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1723" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1723</a></p><p>Returns a chunk from a block position&#39;s x and z coordinates.</p><h5 id="parameters-17" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-17" aria-label="Permalink to “Parameters”">​</a></h5><h6 id="x-3" tabindex="-1">x <a class="header-anchor" href="#x-3" aria-label="Permalink to “x”">​</a></h6><p><code>number</code></p><h6 id="z-2" tabindex="-1">z <a class="header-anchor" href="#z-2" aria-label="Permalink to “z”">​</a></h6><p><code>number</code></p><h5 id="returns-21" tabindex="-1">Returns <a class="header-anchor" href="#returns-21" aria-label="Permalink to “Returns”">​</a></h5><p><code>Promise</code>&lt;<code>Chunk</code>&gt;</p><hr><h3 id="getdimension" tabindex="-1">getDimension() <a class="header-anchor" href="#getdimension" aria-label="Permalink to “getDimension()”">​</a></h3><blockquote><p><strong>getDimension</strong>(): <a href="./../#dimensiontype"><code>DimensionType</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3627" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3627</a></p><p>Which dimension this world is, and therefore how tall it is and where its floor sits.</p><p>Resolved once from the stem&#39;s type by the level. The chunk stack, the disk format and the portal rules all read it from here, so none of them carries its own copy.</p><h4 id="returns-22" tabindex="-1">Returns <a class="header-anchor" href="#returns-22" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#dimensiontype"><code>DimensionType</code></a></p><hr><h3 id="getdragonfight" tabindex="-1">getDragonFight() <a class="header-anchor" href="#getdragonfight" aria-label="Permalink to “getDragonFight()”">​</a></h3><blockquote><p><strong>getDragonFight</strong>(): <code>DragonFight</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2331" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2331</a></p><p>The dragon fight of this world, created on first ask over the state the save held.</p><h4 id="returns-23" tabindex="-1">Returns <a class="header-anchor" href="#returns-23" aria-label="Permalink to “Returns”">​</a></h4><p><code>DragonFight</code> | <code>undefined</code></p><p>The fight, or undefined in a dimension whose type has no <code>has_ender_dragon_fight</code> flag, which is every vanilla dimension but the End.</p><hr><h3 id="getentities" tabindex="-1">getEntities() <a class="header-anchor" href="#getentities" aria-label="Permalink to “getEntities()”">​</a></h3><blockquote><p><strong>getEntities</strong>(): <a href="./Entity.html"><code>Entity</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3271" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3271</a></p><p>Get all entities in this world.</p><h4 id="returns-24" tabindex="-1">Returns <a class="header-anchor" href="#returns-24" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Entity.html"><code>Entity</code></a>[]</p><p>the entities.</p><hr><h3 id="getentity" tabindex="-1">getEntity() <a class="header-anchor" href="#getentity" aria-label="Permalink to “getEntity()”">​</a></h3><blockquote><p><strong>getEntity</strong>(<code>runtimeId</code>): <a href="./Entity.html"><code>Entity</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3395" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3395</a></p><p>One entity, by the id the protocol names it with.</p><p>The map has always been here; only the array of its values was exposed. Everything that arrives from a client naming an entity - an attack, an interaction, a pick - names it by runtime id, and resolving that by walking <code>getEntities()</code> is a linear scan through everything in the world for something the map answers in one step.</p><h4 id="parameters-18" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-18" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="runtimeid" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>bigint</code></p><p>The entity&#39;s runtime id.</p><h4 id="returns-25" tabindex="-1">Returns <a class="header-anchor" href="#returns-25" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Entity.html"><code>Entity</code></a> | <code>null</code></p><p>The entity, or null if nothing here has that id.</p><hr><h3 id="getentitygrid" tabindex="-1">getEntityGrid() <a class="header-anchor" href="#getentitygrid" aria-label="Permalink to “getEntityGrid()”">​</a></h3><blockquote><p><strong>getEntityGrid</strong>(): <code>EntityGrid</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3403" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3403</a></p><p>Where everything is, as of the top of this tick.</p><h4 id="returns-26" tabindex="-1">Returns <a class="header-anchor" href="#returns-26" aria-label="Permalink to “Returns”">​</a></h4><p><code>EntityGrid</code></p><p>The grid, for asking what is near a point.</p><hr><h3 id="getformattedname" tabindex="-1">getFormattedName() <a class="header-anchor" href="#getformattedname" aria-label="Permalink to “getFormattedName()”">​</a></h3><blockquote><p><strong>getFormattedName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3606" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3606</a></p><h4 id="returns-27" tabindex="-1">Returns <a class="header-anchor" href="#returns-27" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getgamerulemanager" tabindex="-1">getGameRuleManager() <a class="header-anchor" href="#getgamerulemanager" aria-label="Permalink to “getGameRuleManager()”">​</a></h3><blockquote><p><strong>getGameRuleManager</strong>(): <code>GameRuleManager</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3571" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3571</a></p><p>The level&#39;s game rules, which every world of the save shares.</p><h4 id="returns-28" tabindex="-1">Returns <a class="header-anchor" href="#returns-28" aria-label="Permalink to “Returns”">​</a></h4><p><code>GameRuleManager</code></p><hr><h3 id="getgenerator" tabindex="-1">getGenerator() <a class="header-anchor" href="#getgenerator" aria-label="Permalink to “getGenerator()”">​</a></h3><blockquote><p><strong>getGenerator</strong>(): <a href="./../#generator"><code>Generator</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L795" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:795</a></p><h4 id="returns-29" tabindex="-1">Returns <a class="header-anchor" href="#returns-29" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#generator"><code>Generator</code></a></p><hr><h3 id="getknownspawnposition" tabindex="-1">getKnownSpawnPosition() <a class="header-anchor" href="#getknownspawnposition" aria-label="Permalink to “getKnownSpawnPosition()”">​</a></h3><blockquote><p><strong>getKnownSpawnPosition</strong>(): <a href="./../../math/classes/Vector3.html"><code>Vector3</code></a> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1977" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1977</a></p><p>The spawn point if it has already been found, and null while it has not.</p><p><a href="#getspawnposition">World.getSpawnPosition</a> searches for dry land the first time it is asked, which is why it is asynchronous. A caller inside the tick cannot wait for that search, so it gets what the world knows now. The Overworld answers the level&#39;s spawn, which is the one the save keeps.</p><h4 id="returns-30" tabindex="-1">Returns <a class="header-anchor" href="#returns-30" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a> | <code>null</code></p><p>The spawn point, or null before it has been resolved.</p><hr><h3 id="getlevel" tabindex="-1">getLevel() <a class="header-anchor" href="#getlevel" aria-label="Permalink to “getLevel()”">​</a></h3><blockquote><p><strong>getLevel</strong>(): <a href="./Level.html"><code>Level</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3561" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3561</a></p><p>The level this world is one dimension of.</p><h4 id="returns-31" tabindex="-1">Returns <a class="header-anchor" href="#returns-31" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Level.html"><code>Level</code></a></p><hr><h3 id="getloadedchunk" tabindex="-1">getLoadedChunk() <a class="header-anchor" href="#getloadedchunk" aria-label="Permalink to “getLoadedChunk()”">​</a></h3><blockquote><p><strong>getLoadedChunk</strong>(<code>cx</code>, <code>cz</code>): <code>Chunk</code> | <code>null</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1210" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1210</a></p><p>The chunk at a coordinate if it is already in memory, and null otherwise.</p><p>The synchronous counterpart to <a href="#getchunk">getChunk</a>, which mob AI needs: pathfinding reads a few hundred blocks to plan one route and has to answer inside the tick, and <code>getChunk</code> would both make that asynchronous and quietly generate terrain as a mob walked towards it. The last answer is remembered, because the callers ask in runs: the light engine scans a column of 384 blocks, and a path finder reads a few hundred around one position, each through this. The cache is one entry and is dropped whenever chunks gains or loses one, so the only way to make it lie is to change the map without going through the load or unload path.</p><h4 id="parameters-19" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-19" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="cx-1" tabindex="-1">cx <a class="header-anchor" href="#cx-1" aria-label="Permalink to “cx”">​</a></h5><p><code>number</code></p><p>Chunk x.</p><h5 id="cz-1" tabindex="-1">cz <a class="header-anchor" href="#cz-1" aria-label="Permalink to “cz”">​</a></h5><p><code>number</code></p><p>Chunk z.</p><h4 id="returns-32" tabindex="-1">Returns <a class="header-anchor" href="#returns-32" aria-label="Permalink to “Returns”">​</a></h4><p><code>Chunk</code> | <code>null</code></p><p>The loaded chunk, or null - never a generated one.</p><hr><h3 id="getloadedchunkcount" tabindex="-1">getLoadedChunkCount() <a class="header-anchor" href="#getloadedchunkcount" aria-label="Permalink to “getLoadedChunkCount()”">​</a></h3><blockquote><p><strong>getLoadedChunkCount</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1228" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1228</a></p><p>How many chunks are in memory, which is what the mob spawner budgets against.</p><h4 id="returns-33" tabindex="-1">Returns <a class="header-anchor" href="#returns-33" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getname" tabindex="-1">getName() <a class="header-anchor" href="#getname" aria-label="Permalink to “getName()”">​</a></h3><blockquote><p><strong>getName</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3603" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3603</a></p><h4 id="returns-34" tabindex="-1">Returns <a class="header-anchor" href="#returns-34" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getplayerdata" tabindex="-1">getPlayerData() <a class="header-anchor" href="#getplayerdata" aria-label="Permalink to “getPlayerData()”">​</a></h3><blockquote><p><strong>getPlayerData</strong>(<code>player</code>): <code>Promise</code>&lt;<code>Partial</code>&lt;<a href="./../#worldplayerdata"><code>WorldPlayerData</code></a>&gt;&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3645" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3645</a></p><p>Get the player data for a player.</p><h4 id="parameters-20" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-20" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-2" tabindex="-1">player <a class="header-anchor" href="#player-2" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>The player to get the data for.</p><h4 id="returns-35" tabindex="-1">Returns <a class="header-anchor" href="#returns-35" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Partial</code>&lt;<a href="./../#worldplayerdata"><code>WorldPlayerData</code></a>&gt;&gt;</p><p>The player data.</p><hr><h3 id="getplayers" tabindex="-1">getPlayers() <a class="header-anchor" href="#getplayers" aria-label="Permalink to “getPlayers()”">​</a></h3><blockquote><p><strong>getPlayers</strong>(): <a href="./Player.html"><code>Player</code></a>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3410" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3410</a></p><p>Get all players in this world.</p><h4 id="returns-36" tabindex="-1">Returns <a class="header-anchor" href="#returns-36" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Player.html"><code>Player</code></a>[]</p><p>the players.</p><hr><h3 id="getportalindex" tabindex="-1">getPortalIndex() <a class="header-anchor" href="#getportalindex" aria-label="Permalink to “getPortalIndex()”">​</a></h3><blockquote><p><strong>getPortalIndex</strong>(): <code>PortalIndex</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2321" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2321</a></p><p>The lit nether portal blocks of this world, kept in step with its block writes and chunk loads.</p><h4 id="returns-37" tabindex="-1">Returns <a class="header-anchor" href="#returns-37" aria-label="Permalink to “Returns”">​</a></h4><p><code>PortalIndex</code></p><hr><h3 id="getprovider" tabindex="-1">getProvider() <a class="header-anchor" href="#getprovider" aria-label="Permalink to “getProvider()”">​</a></h3><blockquote><p><strong>getProvider</strong>(): <a href="./BaseProvider.html"><code>BaseProvider</code></a> &amp; <code>Provider</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3586" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3586</a></p><p>The level&#39;s provider, which serves every dimension of the save.</p><h4 id="returns-38" tabindex="-1">Returns <a class="header-anchor" href="#returns-38" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./BaseProvider.html"><code>BaseProvider</code></a> &amp; <code>Provider</code></p><hr><h3 id="getsealevel" tabindex="-1">getSeaLevel() <a class="header-anchor" href="#getsealevel" aria-label="Permalink to “getSeaLevel()”">​</a></h3><blockquote><p><strong>getSeaLevel</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L807" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:807</a></p><p>The y this world&#39;s generator floods to, which worldgen&#39;s <code>relative_to_sea_level</code> anchors and the content rules that ask about the water line resolve against.</p><p>The generator&#39;s own answer when it has one, which the noise generator reads from its stem&#39;s <code>noise_settings</code> and the flat generator fixes at Java&#39;s -63. A generator without one gets the Overworld&#39;s 63.</p><h4 id="returns-39" tabindex="-1">Returns <a class="header-anchor" href="#returns-39" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getseed" tabindex="-1">getSeed() <a class="header-anchor" href="#getseed" aria-label="Permalink to “getSeed()”">​</a></h3><blockquote><p><strong>getSeed</strong>(): <code>bigint</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3617" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3617</a></p><p>The seed every generated chunk, structure placement and carver in this world comes from.</p><p>A 64-bit value, as Java&#39;s is. It was a <code>number</code> until it turned out that a seed above 2^53 arrived here rounded, which generated a world the player had not asked for.</p><h4 id="returns-40" tabindex="-1">Returns <a class="header-anchor" href="#returns-40" aria-label="Permalink to “Returns”">​</a></h4><p><code>bigint</code></p><hr><h3 id="getserver" tabindex="-1">getServer() <a class="header-anchor" href="#getserver" aria-label="Permalink to “getServer()”">​</a></h3><blockquote><p><strong>getServer</strong>(): <a href="./Server.html"><code>Server</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3732" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3732</a></p><h4 id="returns-41" tabindex="-1">Returns <a class="header-anchor" href="#returns-41" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./Server.html"><code>Server</code></a></p><p>The server instance.</p><hr><h3 id="getspawnposition" tabindex="-1">getSpawnPosition() <a class="header-anchor" href="#getspawnposition" aria-label="Permalink to “getSpawnPosition()”">​</a></h3><blockquote><p><strong>getSpawnPosition</strong>(): <code>Promise</code>&lt;<a href="./../../math/classes/Vector3.html"><code>Vector3</code></a>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1738" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1738</a></p><p>Returns the world spawn, in block coordinates.</p><p>The height is the one <code>level.dat</code> stores, which is one block below where a player&#39;s feet go: see <a href="#placeplayerspawn">placePlayerSpawn</a> for where a player actually starts.</p><h4 id="returns-42" tabindex="-1">Returns <a class="header-anchor" href="#returns-42" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./../../math/classes/Vector3.html"><code>Vector3</code></a>&gt;</p><hr><h3 id="getstem" tabindex="-1">getStem() <a class="header-anchor" href="#getstem" aria-label="Permalink to “getStem()”">​</a></h3><blockquote><p><strong>getStem</strong>(): <a href="./../../worldgen/#levelstem"><code>LevelStem</code></a></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3566" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3566</a></p><p>The stem this world was built from: its dimension type id and its generator definition.</p><h4 id="returns-43" tabindex="-1">Returns <a class="header-anchor" href="#returns-43" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../../worldgen/#levelstem"><code>LevelStem</code></a></p><hr><h3 id="getsystems" tabindex="-1">getSystems() <a class="header-anchor" href="#getsystems" aria-label="Permalink to “getSystems()”">​</a></h3><blockquote><p><strong>getSystems</strong>(): <code>WorldSystems</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2348" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2348</a></p><p>The light engine and the two scheduled tick lists - see WorldSystems.</p><h4 id="returns-44" tabindex="-1">Returns <a class="header-anchor" href="#returns-44" aria-label="Permalink to “Returns”">​</a></h4><p><code>WorldSystems</code></p><hr><h3 id="getticks" tabindex="-1">getTicks() <a class="header-anchor" href="#getticks" aria-label="Permalink to “getTicks()”">​</a></h3><blockquote><p><strong>getTicks</strong>(): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3576" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3576</a></p><p>The level&#39;s clock, which every world of the save shares.</p><h4 id="returns-45" tabindex="-1">Returns <a class="header-anchor" href="#returns-45" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><hr><h3 id="getuuid" tabindex="-1">getUUID() <a class="header-anchor" href="#getuuid" aria-label="Permalink to “getUUID()”">​</a></h3><blockquote><p><strong>getUUID</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3599" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3599</a></p><h4 id="returns-46" tabindex="-1">Returns <a class="header-anchor" href="#returns-46" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="getweather" tabindex="-1">getWeather() <a class="header-anchor" href="#getweather" aria-label="Permalink to “getWeather()”">​</a></h3><blockquote><p><strong>getWeather</strong>(): <code>&quot;thunder&quot;</code> | <code>&quot;clear&quot;</code> | <code>&quot;rain&quot;</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2353" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2353</a></p><p>What the sky is doing: <code>clear</code>, <code>rain</code> or <code>thunder</code>. One answer per level.</p><h4 id="returns-47" tabindex="-1">Returns <a class="header-anchor" href="#returns-47" aria-label="Permalink to “Returns”">​</a></h4><p><code>&quot;thunder&quot;</code> | <code>&quot;clear&quot;</code> | <code>&quot;rain&quot;</code></p><hr><h3 id="hitblock" tabindex="-1">hitBlock() <a class="header-anchor" href="#hitblock" aria-label="Permalink to “hitBlock()”">​</a></h3><blockquote><p><strong>hitBlock</strong>(<code>position</code>, <code>face</code>, <code>striker?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1600" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1600</a></p><p>One swing against a block: the sound of the hit and the chips that come off it.</p><p>Struck, not broken. <code>START_BLOCK_CRACKING</code> was the only thing sent while mining, and that is the progress overlay - it draws the cracks spreading and makes no sound at all, which is why digging was silent until the block gave way.</p><p>The material comes from the runtime id, the same way a break&#39;s destroy event gets it: the client looks the block up and plays whatever that block is made of.</p><p>The sound goes to everyone near but the one striking, whose client plays its own hits in either breaking mode. A Bedrock Dedicated Server 1.26.52 sends the striker none. This one reached them too, and with their client&#39;s own hits it sounded like digging at several times the speed.</p><h4 id="parameters-21" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-21" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-3" tabindex="-1">position <a class="header-anchor" href="#position-3" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The block being struck.</p><h5 id="face" tabindex="-1">face <a class="header-anchor" href="#face" aria-label="Permalink to “face”">​</a></h5><p><code>number</code></p><p>Which side was hit; the chips come off that one.</p><h5 id="striker" tabindex="-1">striker? <a class="header-anchor" href="#striker" aria-label="Permalink to “striker?”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><p>Who is striking it, when a player is.</p><h4 id="returns-48" tabindex="-1">Returns <a class="header-anchor" href="#returns-48" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="israiningat" tabindex="-1">isRainingAt() <a class="header-anchor" href="#israiningat" aria-label="Permalink to “isRainingAt()”">​</a></h3><blockquote><p><strong>isRainingAt</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2381" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2381</a></p><p>Whether rain is falling on one position, Java&#39;s <code>Level.isRainingAt</code>.</p><p>Three of Java&#39;s four conditions: it has to be raining, the position has to see the sky, and nothing may stand above it. The fourth is the biome&#39;s precipitation, which is a temperature curve over the height that neither edition publishes in a form this repository holds, so every biome counts as rainy here and fire in a snowy one is put out where Java would leave it burning.</p><p>The sky test is the light engine&#39;s. Full sky light means an unobstructed column: sky light loses at least one per step the moment it has to travel sideways, so 15 at a position and nowhere short of the sky above it are the same statement. The engine already keeps it per block and updates it with every write, which is the whole reason not to walk the column here - <a href="#topofcolumn">World.topOfColumn</a> answers per chunk at sub chunk resolution, so one block on a hilltop would shelter the whole chunk from the rain.</p><p>It is also Java&#39;s own test rather than an approximation of it. <code>Level.canSeeSky</code> reads the <code>MOTION_BLOCKING</code> heightmap, which a fire does not raise because it has no collision; a fire does not dampen light here either, so the position it stands in still reads 15.</p><h4 id="parameters-22" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-22" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-4" tabindex="-1">x <a class="header-anchor" href="#x-4" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-2" tabindex="-1">y <a class="header-anchor" href="#y-2" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-3" tabindex="-1">z <a class="header-anchor" href="#z-3" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-49" tabindex="-1">Returns <a class="header-anchor" href="#returns-49" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p>False in an unloaded chunk or a dimension without a sky. A loaded chunk outside the simulation light ring is initialized and settled on demand before this test reads it.</p><hr><h3 id="loadchunk" tabindex="-1">loadChunk() <a class="header-anchor" href="#loadchunk" aria-label="Permalink to “loadChunk()”">​</a></h3><blockquote><p><strong>loadChunk</strong>(<code>x</code>, <code>z</code>, <code>options?</code>): <code>Promise</code>&lt;<code>Chunk</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1337" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1337</a></p><p>Loads a chunk in a given x and z and returns its.</p><p>A request for a chunk that is already being loaded joins that one rather than starting a second. They arrive together constantly - the preload asks for a batch of thirty-two in one turn, and every player whose view distance reaches a chunk asks for it as well - and each duplicate was a whole chunk generated and then thrown away, because the last one to finish overwrote the others in the map. Worse than wasted: two callers held two different objects for one position, so a block written into one was invisible through the other.</p><h4 id="parameters-23" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-23" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-5" tabindex="-1">x <a class="header-anchor" href="#x-5" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>x coordinate.</p><h5 id="z-4" tabindex="-1">z <a class="header-anchor" href="#z-4" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>z coordinate.</p><h5 id="options-1" tabindex="-1">options? <a class="header-anchor" href="#options-1" aria-label="Permalink to “options?”">​</a></h5><p><a href="./../#chunkrequestoptions"><code>ChunkRequestOptions</code></a></p><p>How badly the chunk is wanted. A caller that joins a load already in flight and wants it more than whoever started it moves that load up the generator&#39;s queue, so a chunk asked for as the far rim and then stood on does not keep the turn it was given when nobody needed it.</p><h4 id="returns-50" tabindex="-1">Returns <a class="header-anchor" href="#returns-50" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>Chunk</code>&gt;</p><h4 id="throws-1" tabindex="-1">Throws <a class="header-anchor" href="#throws-1" aria-label="Permalink to “Throws”">​</a></h4><p>When the world has been closed, since its provider is gone and a chunk generated now would be generated after the save that was meant to persist it.</p><hr><h3 id="loadedblockat" tabindex="-1">loadedBlockAt() <a class="header-anchor" href="#loadedblockat" aria-label="Permalink to “loadedBlockAt()”">​</a></h3><blockquote><p><strong>loadedBlockAt</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>SystemBlock</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2498" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2498</a></p><p>The block at a position, or undefined when its chunk is not in memory.</p><p>The synchronous read the light engine and the random tick pass need: both run inside the tick and neither may generate terrain by looking at it.</p><h4 id="parameters-24" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-24" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-6" tabindex="-1">x <a class="header-anchor" href="#x-6" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-3" tabindex="-1">y <a class="header-anchor" href="#y-3" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-5" tabindex="-1">z <a class="header-anchor" href="#z-5" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h4 id="returns-51" tabindex="-1">Returns <a class="header-anchor" href="#returns-51" aria-label="Permalink to “Returns”">​</a></h4><p><code>SystemBlock</code> | <code>undefined</code></p><hr><h3 id="loadedblockruntimeidat" tabindex="-1">loadedBlockRuntimeIdAt() <a class="header-anchor" href="#loadedblockruntimeidat" aria-label="Permalink to “loadedBlockRuntimeIdAt()”">​</a></h3><blockquote><p><strong>loadedBlockRuntimeIdAt</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>number</code> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2520" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2520</a></p><p>The runtime id at a position, or undefined where <a href="#loadedblockat">loadedBlockAt</a> has no block.</p><p>The same read without resolving the id to a state, for a caller that keeps a table of its own per runtime id. The light engine does: it wants two numbers per block and asks tens of millions of times while a world preloads, and resolving each of those to a <code>BlockState</code> and then through the property table by name and state values was most of the cost of lighting a chunk.</p><h4 id="parameters-25" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-25" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-7" tabindex="-1">x <a class="header-anchor" href="#x-7" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="y-4" tabindex="-1">y <a class="header-anchor" href="#y-4" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>World y.</p><h5 id="z-6" tabindex="-1">z <a class="header-anchor" href="#z-6" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h4 id="returns-52" tabindex="-1">Returns <a class="header-anchor" href="#returns-52" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code> | <code>undefined</code></p><p>The runtime id, air&#39;s where the column has no sub chunk, and undefined when the chunk is not in memory or <code>y</code> is outside the dimension.</p><hr><h3 id="locatebiome" tabindex="-1">locateBiome() <a class="header-anchor" href="#locatebiome" aria-label="Permalink to “locateBiome()”">​</a></h3><blockquote><p><strong>locateBiome</strong>(<code>name</code>, <code>origin</code>): <a href="./../#biomesearchresult"><code>BiomeSearchResult</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1895" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1895</a></p><p>The nearest cell of a biome, or undefined when there is none within Java&#39;s reach.</p><p>What <code>/locate biome</code> answers. Nothing is generated: the generator walks its climate sampler outward from the origin on Java&#39;s grid, 6400 blocks out at one column per 32 blocks and one sample per 64 blocks of height.</p><h4 id="parameters-26" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-26" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>A biome identifier, with or without its <code>minecraft:</code> namespace, or a <code>#tag</code> such as <code>#minecraft:is_ocean</code>.</p><h5 id="origin" tabindex="-1">origin <a class="header-anchor" href="#origin" aria-label="Permalink to “origin”">​</a></h5><p>Where to search from, in blocks.</p><h6 id="x-8" tabindex="-1">x <a class="header-anchor" href="#x-8" aria-label="Permalink to “x”">​</a></h6><p><code>number</code></p><h6 id="y-5" tabindex="-1">y <a class="header-anchor" href="#y-5" aria-label="Permalink to “y”">​</a></h6><p><code>number</code></p><h6 id="z-7" tabindex="-1">z <a class="header-anchor" href="#z-7" aria-label="Permalink to “z”">​</a></h6><p><code>number</code></p><h4 id="returns-53" tabindex="-1">Returns <a class="header-anchor" href="#returns-53" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#biomesearchresult"><code>BiomeSearchResult</code></a> | <code>undefined</code></p><p>The sampled position, or undefined when the generator has no biome walk of its own, no biome by that name can occur here, or the radius held none.</p><hr><h3 id="locatestructure" tabindex="-1">locateStructure() <a class="header-anchor" href="#locatestructure" aria-label="Permalink to “locateStructure()”">​</a></h3><blockquote><p><strong>locateStructure</strong>(<code>name</code>, <code>origin</code>, <code>radius?</code>): <a href="./../#structuresearchresult"><code>StructureSearchResult</code></a> | <code>undefined</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1855" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1855</a></p><p>The nearest structure whose name matches, or undefined when there is none in range.</p><p>What <code>/locate structure</code> answers. Nothing is generated: the generator lays candidate structures out against the bare noise terrain and reports where the nearest one starts, so the search costs no chunks however far it reaches.</p><h4 id="parameters-27" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-27" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="name-2" tabindex="-1">name <a class="header-anchor" href="#name-2" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>What the player typed. See <a href="./../#structurenamematches">structureNameMatches</a> for how loosely it is read.</p><h5 id="origin-1" tabindex="-1">origin <a class="header-anchor" href="#origin-1" aria-label="Permalink to “origin”">​</a></h5><p>Where to search from, in blocks.</p><h6 id="x-9" tabindex="-1">x <a class="header-anchor" href="#x-9" aria-label="Permalink to “x”">​</a></h6><p><code>number</code></p><h6 id="z-8" tabindex="-1">z <a class="header-anchor" href="#z-8" aria-label="Permalink to “z”">​</a></h6><p><code>number</code></p><h5 id="radius" tabindex="-1">radius? <a class="header-anchor" href="#radius" aria-label="Permalink to “radius?”">​</a></h5><p><code>number</code> = <code>LOCATE_RADIUS</code></p><p>How far out to look, in rings of placement regions; Java&#39;s 100 by default.</p><h4 id="returns-54" tabindex="-1">Returns <a class="header-anchor" href="#returns-54" aria-label="Permalink to “Returns”">​</a></h4><p><a href="./../#structuresearchresult"><code>StructureSearchResult</code></a> | <code>undefined</code></p><p>Java&#39;s locate position and the generation point, or undefined when the generator places no structures, has no search of its own, or found nothing inside the radius.</p><hr><h3 id="movegameeventlistener" tabindex="-1">moveGameEventListener() <a class="header-anchor" href="#movegameeventlistener" aria-label="Permalink to “moveGameEventListener()”">​</a></h3><blockquote><p><strong>moveGameEventListener</strong>(<code>listener</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3241" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3241</a></p><p>Re-files a dynamic game-event listener after its position changes.</p><h4 id="parameters-28" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-28" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="listener-1" tabindex="-1">listener <a class="header-anchor" href="#listener-1" aria-label="Permalink to “listener”">​</a></h5><p><code>GameEventListener</code></p><h4 id="returns-55" tabindex="-1">Returns <a class="header-anchor" href="#returns-55" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="notifyblockbreak" tabindex="-1">notifyBlockBreak() <a class="header-anchor" href="#notifyblockbreak" aria-label="Permalink to “notifyBlockBreak()”">​</a></h3><blockquote><p><strong>notifyBlockBreak</strong>(<code>position</code>, <code>identifier</code>, <code>sourceId?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3224" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3224</a></p><p>Notifies nearby data-driven block sensors that one block broke.</p><h4 id="parameters-29" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-29" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-4" tabindex="-1">position <a class="header-anchor" href="#position-4" aria-label="Permalink to “position”">​</a></h5><p><a href="./../#contentposition"><code>ContentPosition</code></a></p><p>The integer position of the broken block.</p><h5 id="identifier" tabindex="-1">identifier <a class="header-anchor" href="#identifier" aria-label="Permalink to “identifier”">​</a></h5><p><code>string</code></p><p>The namespaced identifier of the broken block.</p><h5 id="sourceid-1" tabindex="-1">sourceId? <a class="header-anchor" href="#sourceid-1" aria-label="Permalink to “sourceId?”">​</a></h5><p><code>number</code></p><p>The runtime id of the player or entity that broke it, when known.</p><h4 id="returns-56" tabindex="-1">Returns <a class="header-anchor" href="#returns-56" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="placeplayerspawn" tabindex="-1">placePlayerSpawn() <a class="header-anchor" href="#placeplayerspawn" aria-label="Permalink to “placePlayerSpawn()”">​</a></h3><blockquote><p><strong>placePlayerSpawn</strong>(<code>random?</code>): <code>Promise</code>&lt;<code>PlayerSpawn</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1924" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1924</a></p><p>Where a player with no saved position starts, chosen the way a Bedrock Dedicated Server chooses it.</p><p>A block nothing registered a behavior for reads as air, so it does not obstruct.</p><h4 id="parameters-30" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-30" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="random" tabindex="-1">random? <a class="header-anchor" href="#random" aria-label="Permalink to “random?”">​</a></h5><p><code>RelocationOffset</code></p><p>picks the offset when the spawn has to move; for tests.</p><h4 id="returns-57" tabindex="-1">Returns <a class="header-anchor" href="#returns-57" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>PlayerSpawn</code>&gt;</p><hr><h3 id="playnamedsound" tabindex="-1">playNamedSound() <a class="header-anchor" href="#playnamedsound" aria-label="Permalink to “playNamedSound()”">​</a></h3><blockquote><p><strong>playNamedSound</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>sound</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1998" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1998</a></p><p>Plays a sound at a block, named the way a resource pack spells it.</p><p>The engine systems and the block behaviors name their sounds - <code>open.door</code>, <code>random.chestopen</code>, <code>random.fizz</code> where lava meets water - and the level sound events the rest of this world sends are numbers out of a fixed client enum with no entry for most of them.</p><h4 id="parameters-31" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-31" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-10" tabindex="-1">x <a class="header-anchor" href="#x-10" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>Block x.</p><h5 id="y-6" tabindex="-1">y <a class="header-anchor" href="#y-6" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>Block y.</p><h5 id="z-9" tabindex="-1">z <a class="header-anchor" href="#z-9" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>Block z.</p><h5 id="sound" tabindex="-1">sound <a class="header-anchor" href="#sound" aria-label="Permalink to “sound”">​</a></h5><p><code>string</code></p><p>The sound definition&#39;s name.</p><h4 id="returns-58" tabindex="-1">Returns <a class="header-anchor" href="#returns-58" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="playnamedsoundat" tabindex="-1">playNamedSoundAt() <a class="header-anchor" href="#playnamedsoundat" aria-label="Permalink to “playNamedSoundAt()”">​</a></h3><blockquote><p><strong>playNamedSoundAt</strong>(<code>position</code>, <code>sound</code>, <code>options?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2012" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2012</a></p><p>Plays a named sound at an exact world-space point.</p><p>The counterpart of <a href="#playnamedsound">World.playNamedSound</a> for things that are not blocks, the way <a href="#spawnnamedparticleat">World.spawnNamedParticleAt</a> is for particles: an entity&#39;s position is already the point, so nothing centers it.</p><h4 id="parameters-32" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-32" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-5" tabindex="-1">position <a class="header-anchor" href="#position-5" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the sound plays.</p><h5 id="sound-1" tabindex="-1">sound <a class="header-anchor" href="#sound-1" aria-label="Permalink to “sound”">​</a></h5><p><code>string</code></p><p>The sound definition&#39;s name.</p><h5 id="options-2" tabindex="-1">options? <a class="header-anchor" href="#options-2" aria-label="Permalink to “options?”">​</a></h5><p><code>NamedSoundOptions</code></p><p>Volume and pitch, when the definition&#39;s own are not wanted.</p><h4 id="returns-59" tabindex="-1">Returns <a class="header-anchor" href="#returns-59" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="randomtickchunks" tabindex="-1">randomTickChunks() <a class="header-anchor" href="#randomtickchunks" aria-label="Permalink to “randomTickChunks()”">​</a></h3><blockquote><p><strong>randomTickChunks</strong>(): <code>RandomTickChunk</code>[]</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2417" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2417</a></p><p>Where this tick&#39;s random draws land: Java&#39;s <code>ServerLevel.tickChunks</code>, in two halves.</p><p>Only a chunk a player ticket holds is simulated, so an empty server draws nothing at all however much of the world is in memory - which is also why nobody&#39;s furnaces burn while they are logged off. And within a chunk, only the sections whose palette holds something that takes random ticks, which is Java&#39;s <code>LevelChunkSection.isRandomlyTicking</code>; see Chunk.getRandomTickSections. The three hundred blocks of air over an Overworld column and the stone under it are both skipped.</p><p>The section test has to be Java&#39;s rather than merely cheap, because the draw state is one counter shared across the world: a section drawn for that Java skips steps the counter and moves every position drawn afterwards. Public for the same reason <a href="#loadedblockat">World.loadedBlockAt</a> is: WorldSystems is handed the world&#39;s reads rather than the world itself.</p><h4 id="returns-60" tabindex="-1">Returns <a class="header-anchor" href="#returns-60" aria-label="Permalink to “Returns”">​</a></h4><p><code>RandomTickChunk</code>[]</p><p>One entry per simulated chunk, with its randomly ticking sections.</p><hr><h3 id="removeentity" tabindex="-1">removeEntity() <a class="header-anchor" href="#removeentity" aria-label="Permalink to “removeEntity()”">​</a></h3><blockquote><p><strong>removeEntity</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2864" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2864</a></p><p>Removes an entity from the level.</p><h4 id="parameters-33" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-33" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-3" tabindex="-1">entity <a class="header-anchor" href="#entity-3" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity to remove.</p><h4 id="returns-61" tabindex="-1">Returns <a class="header-anchor" href="#returns-61" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="removegameeventlistener" tabindex="-1">removeGameEventListener() <a class="header-anchor" href="#removegameeventlistener" aria-label="Permalink to “removeGameEventListener()”">​</a></h3><blockquote><p><strong>removeGameEventListener</strong>(<code>listener</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3246" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3246</a></p><p>Removes a listener from this world&#39;s game-event registries.</p><h4 id="parameters-34" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-34" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="listener-2" tabindex="-1">listener <a class="header-anchor" href="#listener-2" aria-label="Permalink to “listener”">​</a></h5><p><code>GameEventListener</code></p><h4 id="returns-62" tabindex="-1">Returns <a class="header-anchor" href="#returns-62" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="replaystatedigest" tabindex="-1">replayStateDigest() <a class="header-anchor" href="#replaystatedigest" aria-label="Permalink to “replayStateDigest()”">​</a></h3><blockquote><p><strong>replayStateDigest</strong>(): <code>string</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3284" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3284</a></p><p>Hashes loaded chunks, selected pending simulation work, and live entity state for one replay tick.</p><p>Chunks include blocks, biomes, and block entities. Player inventories are included because duplicate or missing stacks can leave every other world field unchanged. Scheduler queues are copied in processing order; lighting is represented by queue depth only, so this digest compares those boundaries but cannot restore them.</p><h4 id="returns-63" tabindex="-1">Returns <a class="header-anchor" href="#returns-63" aria-label="Permalink to “Returns”">​</a></h4><p><code>string</code></p><hr><h3 id="resendblock" tabindex="-1">resendBlock() <a class="header-anchor" href="#resendblock" aria-label="Permalink to “resendBlock()”">​</a></h3><blockquote><p><strong>resendBlock</strong>(<code>x</code>, <code>y</code>, <code>z</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2066" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2066</a></p><p>Tells the players who can see a block what is there, without changing it.</p><p>For a client that predicted a change the server did not make: a refused placement leaves the block that client drew on its screen until something else happens at the position. Nothing is sent for a position whose chunk is not in memory or that lies outside the dimension.</p><h4 id="parameters-35" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-35" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-11" tabindex="-1">x <a class="header-anchor" href="#x-11" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>Block x.</p><h5 id="y-7" tabindex="-1">y <a class="header-anchor" href="#y-7" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>Block y.</p><h5 id="z-10" tabindex="-1">z <a class="header-anchor" href="#z-10" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>Block z.</p><h4 id="returns-64" tabindex="-1">Returns <a class="header-anchor" href="#returns-64" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="save" tabindex="-1">save() <a class="header-anchor" href="#save" aria-label="Permalink to “save()”">​</a></h3><blockquote><p><strong>save</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3474" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3474</a></p><p>Writes this world to disk: every player in it, every changed chunk, the level data.</p><p>Queued behind whatever save is already running rather than run beside it. A caller that asks for a save gets one, so this waits its turn instead of declining like the autosave does, but it never writes at the same time as another pass.</p><h4 id="returns-65" tabindex="-1">Returns <a class="header-anchor" href="#returns-65" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="savechunks" tabindex="-1">saveChunks() <a class="header-anchor" href="#savechunks" aria-label="Permalink to “saveChunks()”">​</a></h3><blockquote><p><strong>saveChunks</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3426" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3426</a></p><p>Saves changed chunks into disk.</p><p>In batches with a yield between them, for the same reason the preload runs in batches: writing a chunk is synchronous, so <code>Promise.all</code> over every changed chunk was one uninterrupted run of work. The first autosave after a start region preload has all 441 chunks to write and held the event loop for ten seconds - the server froze solid, and the tick loop came back announcing it had skipped two hundred ticks.</p><p>A failed chunk write is logged and left dirty for retry. Other chunks in the pass still save, and the next pass tries the failed chunk again.</p><h4 id="returns-66" tabindex="-1">Returns <a class="header-anchor" href="#returns-66" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="saveforreplay" tabindex="-1">saveForReplay() <a class="header-anchor" href="#saveforreplay" aria-label="Permalink to “saveForReplay()”">​</a></h3><blockquote><p><strong>saveForReplay</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3484" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3484</a></p><p>Saves players and chunks for a replay checkpoint, propagating persistence errors.</p><p>Ordinary autosaves log failed writes and retry them later. A replay snapshot must fail instead, because copying the provider after a swallowed error would capture stale state.</p><h4 id="returns-67" tabindex="-1">Returns <a class="header-anchor" href="#returns-67" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="saveleveldata" tabindex="-1">saveLevelData() <a class="header-anchor" href="#saveleveldata" aria-label="Permalink to “saveLevelData()”">​</a></h3><blockquote><p><strong>saveLevelData</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3636" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3636</a></p><p>Writes the level&#39;s metadata through the provider: the spawn, the clock, the rules, the weather and the stems. The level&#39;s, because Bedrock keeps one of each per save; kept here so <code>/setworldspawn</code> and the autosave reach it through the world they hold.</p><h4 id="returns-68" tabindex="-1">Returns <a class="header-anchor" href="#returns-68" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="saveplayerdata" tabindex="-1">savePlayerData() <a class="header-anchor" href="#saveplayerdata" aria-label="Permalink to “savePlayerData()”">​</a></h3><blockquote><p><strong>savePlayerData</strong>(<code>player</code>, <code>requireSuccess?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3679" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3679</a></p><p>Writes a player&#39;s record into the level, filed under World.playerDataKey and stamped with this world&#39;s dimension so the next login puts them back here.</p><h4 id="parameters-36" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-36" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="player-3" tabindex="-1">player <a class="header-anchor" href="#player-3" aria-label="Permalink to “player”">​</a></h5><p><a href="./Player.html"><code>Player</code></a></p><h5 id="requiresuccess" tabindex="-1">requireSuccess? <a class="header-anchor" href="#requiresuccess" aria-label="Permalink to “requireSuccess?”">​</a></h5><p><code>boolean</code> = <code>false</code></p><p>Propagate a persistence error when creating a replay checkpoint.</p><h4 id="returns-69" tabindex="-1">Returns <a class="header-anchor" href="#returns-69" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendactorevent" tabindex="-1">sendActorEvent() <a class="header-anchor" href="#sendactorevent" aria-label="Permalink to “sendActorEvent()”">​</a></h3><blockquote><p><strong>sendActorEvent</strong>(<code>entity</code>, <code>event</code>, <code>data?</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1705" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1705</a></p><p>Tells everyone watching that something happened to one entity - it was hurt, it died, it swung an arm. The client plays the animation and the sound that go with it.</p><h4 id="parameters-37" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-37" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-4" tabindex="-1">entity <a class="header-anchor" href="#entity-4" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The entity it happened to.</p><h5 id="event-1" tabindex="-1">event <a class="header-anchor" href="#event-1" aria-label="Permalink to “event”">​</a></h5><p><a href="./../../minecraft/#actorevent"><code>ActorEvent</code></a></p><p>What happened.</p><h5 id="data" tabindex="-1">data? <a class="header-anchor" href="#data" aria-label="Permalink to “data?”">​</a></h5><p><code>number</code> = <code>0</code></p><p>Extra detail, for the events that carry any.</p><h4 id="returns-70" tabindex="-1">Returns <a class="header-anchor" href="#returns-70" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendactormetadata" tabindex="-1">sendActorMetadata() <a class="header-anchor" href="#sendactormetadata" aria-label="Permalink to “sendActorMetadata()”">​</a></h3><blockquote><p><strong>sendActorMetadata</strong>(<code>entity</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1565" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1565</a></p><p>Tells everyone watching that an entity now looks different.</p><h4 id="parameters-38" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-38" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-5" tabindex="-1">entity <a class="header-anchor" href="#entity-5" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>Who changed.</p><h4 id="returns-71" tabindex="-1">Returns <a class="header-anchor" href="#returns-71" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendactorsound" tabindex="-1">sendActorSound() <a class="header-anchor" href="#sendactorsound" aria-label="Permalink to “sendActorSound()”">​</a></h3><blockquote><p><strong>sendActorSound</strong>(<code>entity</code>, <code>sound</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1557" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1557</a></p><p>A noise one entity made: being hit, dying, swinging at something.</p><h4 id="parameters-39" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-39" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-6" tabindex="-1">entity <a class="header-anchor" href="#entity-6" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>Who made it.</p><h5 id="sound-2" tabindex="-1">sound <a class="header-anchor" href="#sound-2" aria-label="Permalink to “sound”">​</a></h5><p><a href="./../../minecraft/#levelsoundevent"><code>LevelSoundEvent</code></a></p><p>Which noise.</p><h4 id="returns-72" tabindex="-1">Returns <a class="header-anchor" href="#returns-72" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendstatuseffect" tabindex="-1">sendStatusEffect() <a class="header-anchor" href="#sendstatuseffect" aria-label="Permalink to “sendStatusEffect()”">​</a></h3><blockquote><p><strong>sendStatusEffect</strong>(<code>entity</code>, <code>effect</code>, <code>change</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1715" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1715</a></p><p>Tells clients tracking an entity about one status effect change.</p><h4 id="parameters-40" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-40" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="entity-7" tabindex="-1">entity <a class="header-anchor" href="#entity-7" aria-label="Permalink to “entity”">​</a></h5><p><a href="./Entity.html"><code>Entity</code></a></p><p>The actor whose effect changed.</p><h5 id="effect" tabindex="-1">effect <a class="header-anchor" href="#effect" aria-label="Permalink to “effect”">​</a></h5><p><a href="./../#statuseffect"><code>StatusEffect</code></a></p><p>The effect state.</p><h5 id="change" tabindex="-1">change <a class="header-anchor" href="#change" aria-label="Permalink to “change”">​</a></h5><p><a href="./../#statuseffectchange"><code>StatusEffectChange</code></a></p><p>Whether it was added, updated, or removed.</p><h4 id="returns-73" tabindex="-1">Returns <a class="header-anchor" href="#returns-73" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendtime" tabindex="-1">sendTime() <a class="header-anchor" href="#sendtime" aria-label="Permalink to “sendTime()”">​</a></h3><blockquote><p><strong>sendTime</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2820" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2820</a></p><p>Sends the current time to all players in the world.</p><p>Once a second rather than on every tick. The client runs its own day cycle between updates, so twenty of these a second told it nothing it had not already worked out - <code>SetTimePacket</code> is in the default <code>log-excluded-packets</code> purely because of the noise this made.</p><h4 id="returns-74" tabindex="-1">Returns <a class="header-anchor" href="#returns-74" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="sendworldevent" tabindex="-1">sendWorldEvent() <a class="header-anchor" href="#sendworldevent" aria-label="Permalink to “sendWorldEvent()”">​</a></h3><blockquote><p><strong>sendWorldEvent</strong>(<code>position</code>, <code>event</code>, <code>data</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1548" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1548</a></p><p>Sends a world event packet to all the viewers in the position chunk.</p><h4 id="parameters-41" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-41" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-6" tabindex="-1">position <a class="header-anchor" href="#position-6" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a> | <code>null</code></p><p>world position.</p><h5 id="event-2" tabindex="-1">event <a class="header-anchor" href="#event-2" aria-label="Permalink to “event”">​</a></h5><p><a href="./../../minecraft/#levelevent"><code>LevelEvent</code></a></p><p>event identifier.</p><h5 id="data-1" tabindex="-1">data <a class="header-anchor" href="#data-1" aria-label="Permalink to “data”">​</a></h5><p><code>number</code></p><p>event data.</p><h4 id="returns-75" tabindex="-1">Returns <a class="header-anchor" href="#returns-75" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="setblockbyname" tabindex="-1">setBlockByName() <a class="header-anchor" href="#setblockbyname" aria-label="Permalink to “setBlockByName()”">​</a></h3><blockquote><p><strong>setBlockByName</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>name</code>, <code>now?</code>, <code>delay?</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2301" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2301</a></p><p>The same, for a block in its default state.</p><h4 id="parameters-42" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-42" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-12" tabindex="-1">x <a class="header-anchor" href="#x-12" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="y-8" tabindex="-1">y <a class="header-anchor" href="#y-8" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>World y.</p><h5 id="z-11" tabindex="-1">z <a class="header-anchor" href="#z-11" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h5 id="name-3" tabindex="-1">name <a class="header-anchor" href="#name-3" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The block&#39;s namespace id.</p><h5 id="now" tabindex="-1">now? <a class="header-anchor" href="#now" aria-label="Permalink to “now?”">​</a></h5><p><code>number</code> = <code>...</code></p><p>The tick to schedule the resulting updates from.</p><h5 id="delay" tabindex="-1">delay? <a class="header-anchor" href="#delay" aria-label="Permalink to “delay?”">​</a></h5><p><code>number</code> = <code>1</code></p><p>Ticks before the neighbors are looked at.</p><h4 id="returns-76" tabindex="-1">Returns <a class="header-anchor" href="#returns-76" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p><code>false</code> if nothing changed, or this server has no such block.</p><hr><h3 id="setblockruntimeid" tabindex="-1">setBlockRuntimeId() <a class="header-anchor" href="#setblockruntimeid" aria-label="Permalink to “setBlockRuntimeId()”">​</a></h3><blockquote><p><strong>setBlockRuntimeId</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>runtimeId</code>, <code>now?</code>, <code>delay?</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2180" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2180</a></p><p>The one way a block changes.</p><p>Everything a block change has to do, in one place: write it, tell every client, and give the blocks around it a chance to react. Routing every change through here is what makes physics work at all - a caller that writes into the chunk directly changes the world without anything noticing, so the sand above stays in mid air and the water beside it never moves.</p><h4 id="parameters-43" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-43" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-13" tabindex="-1">x <a class="header-anchor" href="#x-13" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="y-9" tabindex="-1">y <a class="header-anchor" href="#y-9" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>World y.</p><h5 id="z-12" tabindex="-1">z <a class="header-anchor" href="#z-12" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h5 id="runtimeid-1" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid-1" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>number</code></p><p>The block state to put there.</p><h5 id="now-1" tabindex="-1">now? <a class="header-anchor" href="#now-1" aria-label="Permalink to “now?”">​</a></h5><p><code>number</code> = <code>...</code></p><p>The tick to schedule the resulting updates from.</p><h5 id="delay-1" tabindex="-1">delay? <a class="header-anchor" href="#delay-1" aria-label="Permalink to “delay?”">​</a></h5><p><code>number</code> = <code>1</code></p><p>Ticks before the neighbors are looked at.</p><h4 id="returns-77" tabindex="-1">Returns <a class="header-anchor" href="#returns-77" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p><code>false</code> if nothing changed - the position is outside the world, its chunk is not loaded, or that block is already there.</p><hr><h3 id="setloadedblockruntimeid" tabindex="-1">setLoadedBlockRuntimeId() <a class="header-anchor" href="#setloadedblockruntimeid" aria-label="Permalink to “setLoadedBlockRuntimeId()”">​</a></h3><blockquote><p><strong>setLoadedBlockRuntimeId</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>runtimeId</code>, <code>now?</code>, <code>delay?</code>, <code>notifyNeighbors?</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2211" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2211</a></p><p>The same write, for a chunk that is already in memory.</p><p><a href="#setblockruntimeid">World.setBlockRuntimeId</a> is this method with a chunk load in front of it. The split exists because the content behaviors write blocks from inside the tick and cannot await: a door has to see its own other half the moment it writes it, and generating terrain because a behavior looked at a position would be worse than declining to write.</p><h4 id="parameters-44" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-44" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-14" tabindex="-1">x <a class="header-anchor" href="#x-14" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="y-10" tabindex="-1">y <a class="header-anchor" href="#y-10" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>World y.</p><h5 id="z-13" tabindex="-1">z <a class="header-anchor" href="#z-13" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h5 id="runtimeid-2" tabindex="-1">runtimeId <a class="header-anchor" href="#runtimeid-2" aria-label="Permalink to “runtimeId”">​</a></h5><p><code>number</code></p><p>The block state to put there.</p><h5 id="now-2" tabindex="-1">now? <a class="header-anchor" href="#now-2" aria-label="Permalink to “now?”">​</a></h5><p><code>number</code> = <code>...</code></p><p>The tick to schedule the resulting updates from.</p><h5 id="delay-2" tabindex="-1">delay? <a class="header-anchor" href="#delay-2" aria-label="Permalink to “delay?”">​</a></h5><p><code>number</code> = <code>1</code></p><p>Ticks before the neighbors are looked at.</p><h5 id="notifyneighbors" tabindex="-1">notifyNeighbors? <a class="header-anchor" href="#notifyneighbors" aria-label="Permalink to “notifyNeighbors?”">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>Whether to run the engine updates the change causes. Java&#39;s flag 1 in <code>setBlockAndUpdate</code>, against the bare write a diode uses for its own state.</p><h4 id="returns-78" tabindex="-1">Returns <a class="header-anchor" href="#returns-78" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>false</code> if nothing changed, including when the chunk is not in memory.</p><hr><h3 id="setloadedblockstate" tabindex="-1">setLoadedBlockState() <a class="header-anchor" href="#setloadedblockstate" aria-label="Permalink to “setLoadedBlockState()”">​</a></h3><blockquote><p><strong>setLoadedBlockState</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>block</code>, <code>notifyNeighbors</code>): <code>boolean</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2235" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2235</a></p><p>The same write, naming the block by its state rather than by its runtime id.</p><p>What the engine systems write through - see import(&#39;./EngineWorld&#39;). They carry a Bedrock identifier and a state record and know nothing of runtime ids, and a state this server&#39;s palette does not hold is declined rather than guessed at.</p><h4 id="parameters-45" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-45" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-15" tabindex="-1">x <a class="header-anchor" href="#x-15" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><h5 id="y-11" tabindex="-1">y <a class="header-anchor" href="#y-11" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><h5 id="z-14" tabindex="-1">z <a class="header-anchor" href="#z-14" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><h5 id="block-1" tabindex="-1">block <a class="header-anchor" href="#block-1" aria-label="Permalink to “block”">​</a></h5><p><code>SystemBlock</code></p><h5 id="notifyneighbors-1" tabindex="-1">notifyNeighbors <a class="header-anchor" href="#notifyneighbors-1" aria-label="Permalink to “notifyNeighbors”">​</a></h5><p><code>boolean</code></p><p>Whether to run the engine updates the change causes.</p><h4 id="returns-79" tabindex="-1">Returns <a class="header-anchor" href="#returns-79" aria-label="Permalink to “Returns”">​</a></h4><p><code>boolean</code></p><p><code>false</code> if nothing changed.</p><hr><h3 id="setspawnposition" tabindex="-1">setSpawnPosition() <a class="header-anchor" href="#setspawnposition" aria-label="Permalink to “setSpawnPosition()”">​</a></h3><blockquote><p><strong>setSpawnPosition</strong>(<code>pos</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1963" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1963</a></p><p>Set the world&#39;s spawn position. The Overworld&#39;s is the level&#39;s, Bedrock&#39;s <code>SpawnX/Y/Z</code>.</p><h4 id="parameters-46" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-46" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="pos" tabindex="-1">pos <a class="header-anchor" href="#pos" aria-label="Permalink to “pos”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The position.</p><h4 id="returns-80" tabindex="-1">Returns <a class="header-anchor" href="#returns-80" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setticks" tabindex="-1">setTicks() <a class="header-anchor" href="#setticks" aria-label="Permalink to “setTicks()”">​</a></h3><blockquote><p><strong>setTicks</strong>(<code>tick</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L3581" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:3581</a></p><p>Sets the level&#39;s clock, which is what <code>/time set</code> does.</p><h4 id="parameters-47" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-47" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick" tabindex="-1">tick <a class="header-anchor" href="#tick" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><h4 id="returns-81" tabindex="-1">Returns <a class="header-anchor" href="#returns-81" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="setweather" tabindex="-1">setWeather() <a class="header-anchor" href="#setweather" aria-label="Permalink to “setWeather()”">​</a></h3><blockquote><p><strong>setWeather</strong>(<code>kind</code>, <code>durationTicks?</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2395" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2395</a></p><p>Sets the weather, which is what <code>/weather &lt;kind&gt; [duration]</code> does.</p><h4 id="parameters-48" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-48" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="kind" tabindex="-1">kind <a class="header-anchor" href="#kind" aria-label="Permalink to “kind”">​</a></h5><p><code>&quot;thunder&quot;</code> | <code>&quot;clear&quot;</code> | <code>&quot;rain&quot;</code></p><p><code>clear</code>, <code>rain</code> or <code>thunder</code>.</p><h5 id="durationticks" tabindex="-1">durationTicks? <a class="header-anchor" href="#durationticks" aria-label="Permalink to “durationTicks?”">​</a></h5><p><code>number</code></p><p>How long, in ticks. Left out, each kind gets Java&#39;s own randomized default: 10 to 150 minutes clear, 10 to 20 raining, 3 to 13 storming.</p><h4 id="returns-82" tabindex="-1">Returns <a class="header-anchor" href="#returns-82" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="spawnnamedparticle" tabindex="-1">spawnNamedParticle() <a class="header-anchor" href="#spawnnamedparticle" aria-label="Permalink to “spawnNamedParticle()”">​</a></h3><blockquote><p><strong>spawnNamedParticle</strong>(<code>x</code>, <code>y</code>, <code>z</code>, <code>particle</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2042" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2042</a></p><p>Emits a named particle effect at a block, such as <code>minecraft:crop_growth_emitter</code>.</p><p>The counterpart of <a href="#playnamedsound">World.playNamedSound</a>: the hardcoded effects <a href="#sendworldevent">World.sendWorldEvent</a> carries are numbered, and the ones a behavior pack can name are not.</p><h4 id="parameters-49" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-49" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-16" tabindex="-1">x <a class="header-anchor" href="#x-16" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>Block x.</p><h5 id="y-12" tabindex="-1">y <a class="header-anchor" href="#y-12" aria-label="Permalink to “y”">​</a></h5><p><code>number</code></p><p>Block y.</p><h5 id="z-15" tabindex="-1">z <a class="header-anchor" href="#z-15" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>Block z.</p><h5 id="particle" tabindex="-1">particle <a class="header-anchor" href="#particle" aria-label="Permalink to “particle”">​</a></h5><p><code>string</code></p><p>The effect&#39;s identifier.</p><h4 id="returns-83" tabindex="-1">Returns <a class="header-anchor" href="#returns-83" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="spawnnamedparticleat" tabindex="-1">spawnNamedParticleAt() <a class="header-anchor" href="#spawnnamedparticleat" aria-label="Permalink to “spawnNamedParticleAt()”">​</a></h3><blockquote><p><strong>spawnNamedParticleAt</strong>(<code>position</code>, <code>particle</code>): <code>void</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2051" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2051</a></p><p>Emits a named particle effect at an exact world-space point.</p><h4 id="parameters-50" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-50" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-7" tabindex="-1">position <a class="header-anchor" href="#position-7" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>Where the effect appears.</p><h5 id="particle-1" tabindex="-1">particle <a class="header-anchor" href="#particle-1" aria-label="Permalink to “particle”">​</a></h5><p><code>string</code></p><p>The effect&#39;s identifier.</p><h4 id="returns-84" tabindex="-1">Returns <a class="header-anchor" href="#returns-84" aria-label="Permalink to “Returns”">​</a></h4><p><code>void</code></p><hr><h3 id="startblockcracking" tabindex="-1">startBlockCracking() <a class="header-anchor" href="#startblockcracking" aria-label="Permalink to “startBlockCracking()”">​</a></h3><blockquote><p><strong>startBlockCracking</strong>(<code>position</code>, <code>face</code>, <code>tool</code>, <code>previous</code>): <code>Promise</code>&lt;<code>BlockMining</code> | <code>null</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1626" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1626</a></p><p>Starts the crack animation on a block a player began mining, as a Bedrock Dedicated Server does with server-authoritative block breaking.</p><p>The cracks on whatever the player mined before stop first, then start on this block with the progress a tick is worth. They continue every tick through <a href="#updateblockcracking">World.updateBlockCracking</a> until the block breaks or the player stops.</p><h4 id="parameters-51" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-51" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-8" tabindex="-1">position <a class="header-anchor" href="#position-8" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The block being mined.</p><h5 id="face-1" tabindex="-1">face <a class="header-anchor" href="#face-1" aria-label="Permalink to “face”">​</a></h5><p><code>number</code></p><p>The face being mined, which decides where the particles fly.</p><h5 id="tool" tabindex="-1">tool <a class="header-anchor" href="#tool" aria-label="Permalink to “tool”">​</a></h5><p><a href="./Item.html"><code>Item</code></a> | <code>null</code></p><p>What the player holds, or null for a bare hand.</p><h5 id="previous" tabindex="-1">previous <a class="header-anchor" href="#previous" aria-label="Permalink to “previous”">​</a></h5><p><code>BlockMining</code> | <code>null</code></p><p>What the player was mining until now.</p><h4 id="returns-85" tabindex="-1">Returns <a class="header-anchor" href="#returns-85" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>BlockMining</code> | <code>null</code>&gt;</p><p>What the player is mining now, or null for air and for a block that breaks at once, which have nothing to animate.</p><hr><h3 id="stopblockcracking" tabindex="-1">stopBlockCracking() <a class="header-anchor" href="#stopblockcracking" aria-label="Permalink to “stopBlockCracking()”">​</a></h3><blockquote><p><strong>stopBlockCracking</strong>(<code>position</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1694" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1694</a></p><p>Ends the crack animation on a block, as when the player stops mining it or moves on.</p><h4 id="parameters-52" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-52" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="position-9" tabindex="-1">position <a class="header-anchor" href="#position-9" aria-label="Permalink to “position”">​</a></h5><p><a href="./../../math/classes/Vector3.html"><code>Vector3</code></a></p><p>The block.</p><h4 id="returns-86" tabindex="-1">Returns <a class="header-anchor" href="#returns-86" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="topofcolumn" tabindex="-1">topOfColumn() <a class="header-anchor" href="#topofcolumn" aria-label="Permalink to “topOfColumn()”">​</a></h3><blockquote><p><strong>topOfColumn</strong>(<code>x</code>, <code>z</code>): <code>number</code></p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L2537" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:2537</a></p><p>One past the highest y a column stores a block for - see Chunk.getTopStoredY.</p><p>Public for the same reason <a href="#loadedblockat">loadedBlockAt</a> is. A chunk that is not in memory answers with the dimension ceiling, because the only safe answer about a column nothing can read is that something might stand anywhere in it.</p><h4 id="parameters-53" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-53" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="x-17" tabindex="-1">x <a class="header-anchor" href="#x-17" aria-label="Permalink to “x”">​</a></h5><p><code>number</code></p><p>World x.</p><h5 id="z-16" tabindex="-1">z <a class="header-anchor" href="#z-16" aria-label="Permalink to “z”">​</a></h5><p><code>number</code></p><p>World z.</p><h4 id="returns-87" tabindex="-1">Returns <a class="header-anchor" href="#returns-87" aria-label="Permalink to “Returns”">​</a></h4><p><code>number</code></p><p>One past the highest stored y.</p><hr><h3 id="update" tabindex="-1">update() <a class="header-anchor" href="#update" aria-label="Permalink to “update()”">​</a></h3><blockquote><p><strong>update</strong>(<code>tick</code>): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L945" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:945</a></p><p>Called every tick.</p><h4 id="parameters-54" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-54" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="tick-1" tabindex="-1">tick <a class="header-anchor" href="#tick-1" aria-label="Permalink to “tick”">​</a></h5><p><code>number</code></p><h4 id="returns-88" tabindex="-1">Returns <a class="header-anchor" href="#returns-88" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><hr><h3 id="updateblockcracking" tabindex="-1">updateBlockCracking() <a class="header-anchor" href="#updateblockcracking" aria-label="Permalink to “updateBlockCracking()”">​</a></h3><blockquote><p><strong>updateBlockCracking</strong>(<code>mining</code>): <code>Promise</code>&lt;<code>boolean</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L1670" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:1670</a></p><p>One tick of mining: the particles off the face being mined, then the crack progress.</p><p>A Bedrock Dedicated Server sends this pair every tick for as long as a block is being mined. The particles leave from the block&#39;s center and carry its runtime id, which the client textures them with. The progress goes to the block&#39;s corner, like the start and the stop.</p><p>The block can change while it is mined: another player breaks it, or a command or a flood replaces it. The cracks belonged to the block that was there, so they stop with it.</p><h4 id="parameters-55" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-55" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="mining" tabindex="-1">mining <a class="header-anchor" href="#mining" aria-label="Permalink to “mining”">​</a></h5><p><code>BlockMining</code></p><p>What is being mined.</p><h4 id="returns-89" tabindex="-1">Returns <a class="header-anchor" href="#returns-89" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>boolean</code>&gt;</p><p>False when the block is no longer the one being mined, in which case its cracks were stopped and nothing else was sent.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to “Lifecycle”">​</a></h2><h3 id="disable" tabindex="-1">disable() <a class="header-anchor" href="#disable" aria-label="Permalink to “disable()”">​</a></h3><blockquote><p><strong>disable</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L784" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:784</a></p><p>On disable hook.</p><p>The order is the whole of it. Marking the world closing stops the preload asking for more chunks and stops the tick; waiting for the start region means every chunk that was generated is in <code>this.chunks</code> before the save walks it; and the provider is closed last, once nothing is left that could ask it for anything.</p><p>An autosave a tick started is one of those things. <a href="#save">World.save</a> waits for it before writing anything of its own, so by the time the level closes the provider no write is outstanding - closing the database under one is the same failure the start region race used to cause. The provider itself is the level&#39;s to close, once every world of the save has been through this.</p><h4 id="returns-90" tabindex="-1">Returns <a class="header-anchor" href="#returns-90" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="implementation-of" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./Service.html"><code>Service</code></a>.<a href="./Service.html#disable"><code>disable</code></a></p><hr><h3 id="enable" tabindex="-1">enable() <a class="header-anchor" href="#enable" aria-label="Permalink to “enable()”">​</a></h3><blockquote><p><strong>enable</strong>(): <code>Promise</code>&lt;<code>void</code>&gt;</p></blockquote><p>Defined in: <a href="https://github.com/JSPrismarine/JSPrismarine/blob/be5d8d027f8aa4710091ae758f91941bf2932a48/packages/prismarine/src/world/World.ts#L694" target="_blank" rel="noreferrer">prismarine/src/world/World.ts:694</a></p><p>On enable hook: puts back what the save kept for this dimension and generates the start region, unless <a href="./../#startregion">WorldData.startRegion</a> defers it. The level has opened the provider and read the save-level state by now.</p><h4 id="returns-91" tabindex="-1">Returns <a class="header-anchor" href="#returns-91" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<code>void</code>&gt;</p><h4 id="implementation-of-1" tabindex="-1">Implementation of <a class="header-anchor" href="#implementation-of-1" aria-label="Permalink to “Implementation of”">​</a></h4><p><a href="./Service.html"><code>Service</code></a>.<a href="./Service.html#enable"><code>enable</code></a></p>`,1171)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};